import{_ as n,o as t,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Endpunkte","description":"","frontmatter":{},"headers":[],"relativePath":"de/concepts/endpoints.md","filePath":"de/concepts/endpoints.md","lastUpdated":1784903584000}'),d={name:"de/concepts/endpoints.md"};function i(r,e,p,o,u,l){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="endpunkte" tabindex="-1">Endpunkte <a class="header-anchor" href="#endpunkte" aria-label="Permalink to &quot;Endpunkte&quot;">​</a></h1><p>Ein Endpunkt ist eine bestimmte HTTP-Methode + Pfad, der aufgerufen werden kann (z. B. <code>GET /api/users/{id}</code>). Endpunkte sind die eigentlichen API-Operationen, die der LLM entdeckt, inspiziert und aufruft.</p><h2 id="struktur" tabindex="-1">Struktur <a class="header-anchor" href="#struktur" aria-label="Permalink to &quot;Struktur&quot;">​</a></h2><p>Jeder Endpunkt enthält:</p><ul><li><strong>HTTP-Methode</strong>: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS</li><li><strong>Pfad</strong>: <code>/api/v1/users/{id}</code></li><li><strong>Zusammenfassung</strong>: eine kurze Beschreibung dessen, was der Endpunkt tut — sehr nützlich für den LLM, um seinen Zweck auf einen Blick zu verstehen</li><li><strong>Beschreibung</strong>: eine detaillierte Erklärung des Verhaltens, der Parameter und der Anwendungsfälle des Endpunkts</li><li><strong>Parameter</strong>: Pfad, Abfrage, Header, Cookie</li><li><strong>Anforderungstext</strong>: für POST/PUT/PATCH</li><li><strong>Antworten</strong>: Statuscodes und Antwortschemata</li></ul><p>Die Felder <code>summary</code> und <code>description</code> stammen aus der OpenAPI/Swagger/Postman-Datei. Sie sind der primäre Weg, wie der LLM versteht, was ein Endpunkt tut. Gut geschriebene Zusammenfassungen machen die Endpunkterkennung viel effektiver.</p><h2 id="mcp-tools-fur-endpunkte" tabindex="-1">MCP-Tools für Endpunkte <a class="header-anchor" href="#mcp-tools-fur-endpunkte" aria-label="Permalink to &quot;MCP-Tools für Endpunkte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>Alle Endpunkte in einer Spec</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Endpunkte in einer Collection</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Endpunkte in einem Tag</td></tr><tr><td><code>endpoint_by_id</code></td><td>Kurze Endpunktzusammenfassung</td></tr><tr><td><code>inspect</code></td><td>Vollständige Endpunktdetails (Schemata, Parameter)</td></tr><tr><td><code>invoke</code></td><td>Endpunkt aufrufen</td></tr><tr><td><code>search</code></td><td>Endpunkte nach Text durchsuchen</td></tr></tbody></table><h2 id="veraltete-endpunkte" tabindex="-1">Veraltete Endpunkte <a class="header-anchor" href="#veraltete-endpunkte" aria-label="Permalink to &quot;Veraltete Endpunkte&quot;">​</a></h2><p>Endpunkte, die in der Spezifikation als <code>deprecated</code> markiert sind, werden bei der Inspektion mit einem Hinweis angezeigt.</p><h2 id="konfiguration" tabindex="-1">Konfiguration <a class="header-anchor" href="#konfiguration" aria-label="Permalink to &quot;Konfiguration&quot;">​</a></h2><p>Endpunkte sind aus der Perspektive von swag2mcp <strong>schreibgeschützt</strong>. Es gibt keine YAML-Konfigurationseinstellungen für Endpunkte — Sie können sie in <code>swag2mcp.yaml</code> nicht hinzufügen, entfernen, umbenennen oder ändern.</p><p>Um Endpunkte zu ändern (neue hinzufügen, Zusammenfassungen aktualisieren, Parameter ändern, als veraltet markieren), bearbeiten Sie die ursprüngliche OpenAPI/Swagger/Postman-Datei und führen Sie <code>swag2mcp update</code> aus, um neu zu parsen und neu zu indizieren.</p><h2 id="beispiel" tabindex="-1">Beispiel <a class="header-anchor" href="#beispiel" aria-label="Permalink to &quot;Beispiel&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Abfrage: &quot;Zeige Details für GET /pet/{petId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ Ergebnis:</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  Zusammenfassung: Haustier nach ID finden</span></span>
<span class="line"><span>  Beschreibung: Gibt ein einzelnes Haustier anhand seiner ID zurück</span></span>
<span class="line"><span>  Parameter:</span></span>
<span class="line"><span>    - petId (path, integer, erforderlich)</span></span>
<span class="line"><span>  Antworten:</span></span>
<span class="line"><span>    - 200: Pet-Objekt</span></span>
<span class="line"><span>    - 400: Fehler</span></span>
<span class="line"><span>    - 404: Nicht gefunden</span></span></code></pre></div>`,15)])])}const g=n(d,[["render",i]]);export{h as __pageData,g as default};
